import randomfrom statistics import meanfrom order import Orderfrom matching_engine import MatchingEnginedef seed_order_book(engine, start_id=1):    order_id = start_id    # Create initial liquidity around a price of 100    for price in [99.50, 99.60, 99.70, 99.80, 99.90]:        order = Order(            order_id,            "BUY",            "LIMIT",            200,            price,            order_id        )        engine.process_order(order)        order_id += 1    for price in [100.10, 100.20, 100.30, 100.40, 100.50]:        order = Order(            order_id,            "SELL",            "LIMIT",            200,            price,            order_id        )        engine.process_order(order)        order_id += 1    return order_iddef run_simulation(number_of_orders=1000):    engine = MatchingEngine()    order_id = seed_order_book(engine)    spreads = []    market_order_slippage = []    market_orders = 0    for _ in range(number_of_orders):        side = random.choice(["BUY", "SELL"])        # 80% limit orders, 20% market orders        order_type = random.choices(            ["LIMIT", "MARKET"],            weights=[0.8, 0.2]        )[0]        quantity = random.randint(10, 100)        best_bid = engine.order_book.best_bid()        best_ask = engine.order_book.best_ask()        # Record spread whenever both sides exist        if best_bid is not None and best_ask is not None:            spreads.append(best_ask - best_bid)        if order_type == "LIMIT":            # Generate prices around 100            if side == "BUY":                price = round(random.uniform(99.0, 100.2), 2)            else:                price = round(random.uniform(99.8, 101.0), 2)            order = Order(                order_id,                side,                "LIMIT",                quantity,                price,                order_id            )            engine.process_order(order)        else:            market_orders += 1            # Need liquidity on the opposite side            if side == "BUY" and best_ask is None:                order_id += 1                continue            if side == "SELL" and best_bid is None:                order_id += 1                continue            trades_before = len(engine.trades)            order = Order(                order_id,                side,                "MARKET",                quantity,                None,                order_id            )            engine.process_order(order)            new_trades = engine.trades[trades_before:]            if new_trades:                total_quantity = sum(                    trade.quantity for trade in new_trades                )                average_execution_price = sum(                    trade.price * trade.quantity                    for trade in new_trades                ) / total_quantity                if side == "BUY":                    slippage = average_execution_price - best_ask                else:                    slippage = best_bid - average_execution_price                market_order_slippage.append(slippage)        order_id += 1    print("Simulation complete")    print("-------------------")    print("Orders submitted:", number_of_orders)    print("Trades executed:", len(engine.trades))    print("Market orders submitted:", market_orders)    if spreads:        print("Average bid-ask spread:", round(mean(spreads), 4))    if market_order_slippage:        print(            "Average market-order slippage:",            round(mean(market_order_slippage), 4)        )if __name__ == "__main__":    run_simulation(1000)